function mat(color,roughness=.42,metalness=0){return new THREE.MeshStandardMaterial({color,roughness,metalness})}
function fruit(name){const g=new THREE.Group();const red=name==='Strawberry'||name==='Raspberry'||name==='Cherry';const berryColor=name==='Blueberry'?'#435b9c':name==='Cherry'?'#bd294d':name==='Raspberry'?'#cd4167':name==='Strawberry'?'#e64759':'#57333c';if(name==='Strawberry'){const b=new THREE.Mesh(new THREE.ConeGeometry(.12,.28,12),mat(berryColor,.32));b.rotation.x=Math.PI;b.position.y=.12;g.add(b);for(let i=0;i<8;i++){const dot=new THREE.Mesh(new THREE.SphereGeometry(.012,6,6),mat('#ffe3a3'));const a=i*2.4;dot.position.set(Math.cos(a)*.075,.07+(i%3)*.035,Math.sin(a)*.075);g.add(dot)}const leaf=new THREE.Mesh(new THREE.ConeGeometry(.08,.09,7),mat('#4b9b69'));leaf.position.y=.25;g.add(leaf)}else if(name==='Raspberry'){for(let y=0;y<3;y++)for(let i=0;i<5-y;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(.052,10,8),mat(berryColor,.3));const a=i*1.25+y*.38;b.position.set(Math.cos(a)*.055,y*.065,Math.sin(a)*.055);g.add(b)}}else{const b=new THREE.Mesh(new THREE.SphereGeometry(name==='Cherry'?.12:.11,18,14),mat(berryColor,.26));b.scale.set(1,.86,1);g.add(b);if(name==='Cherry'){const stem=new THREE.Mesh(new THREE.CylinderGeometry(.009,.013,.21,6),mat('#63834e'));stem.position.set(.03,.15,0);stem.rotation.z=-.22;g.add(stem);const shine=new THREE.Mesh(new THREE.SphereGeometry(.024,8,7),mat('#ffe0e4'));shine.position.set(-.04,.04,.085);g.add(shine)}}return g}
function petalFlower(){const g=new THREE.Group();for(let i=0;i<7;i++){const a=i/7*Math.PI*2;const p=new THREE.Mesh(new THREE.SphereGeometry(.07,12,10),mat(i%2?'#fff5cf':'#f3a5bd',.36));p.scale.set(.74,1.3,.55);p.position.set(Math.cos(a)*.09,.025,Math.sin(a)*.09);p.rotation.y=-a;g.add(p)}const c=new THREE.Mesh(new THREE.SphereGeometry(.055,12,8),mat('#f2c85e'));c.position.y=.06;g.add(c);return g}
function heartGeometry(){const s=new THREE.Shape();s.moveTo(0,-.17);s.bezierCurveTo(-.08,-.08,-.27,.05,-.21,.17);s.bezierCurveTo(-.16,.27,-.04,.22,0,.15);s.bezierCurveTo(.05,.24,.19,.27,.23,.15);s.bezierCurveTo(.28,.04,.08,-.09,0,-.17);return new THREE.ExtrudeGeometry(s,{depth:.045,bevelEnabled:true,bevelSize:.018,bevelThickness:.018,bevelSegments:2,curveSegments:8})}
