if(name==='Chocolate'||name==='Mini cookie'||name==='Macaron'){let color=name==='Chocolate'?'#75473d':name==='Macaron'?'#d892a8':'#c99362';if(name==='Chocolate'){const b=new THREE.Mesh(new THREE.BoxGeometry(.27,.12,.19),mat(color,.3));b.rotation.y=.35;g.add(b);for(let i=0;i<3;i++){const s=new THREE.Mesh(new THREE.BoxGeometry(.075,.035,.075),mat('#9a6857'));s.position.set((i-1)*.08,.075,0);g.add(s)}}else{const b=new THREE.Mesh(new THREE.CylinderGeometry(.15,.15,.1,24),mat(color,.34));g.add(b);const cream=new THREE.Mesh(new THREE.TorusGeometry(.115,.018,7,24),mat('#fff0d9'));cream.rotation.x=Math.PI/2;cream.position.y=.01;g.add(cream)}return g}
if(name==='Pearls'||name==='Sprinkles'){const count=name==='Pearls'?4:6;for(let i=0;i<count;i++){const color=name==='Pearls'?'#fff7e6':['#e45c88','#edbd46','#73b9d1','#8bbd88'][i%4];const b=new THREE.Mesh(name==='Pearls'?new THREE.SphereGeometry(.046,12,10):new THREE.CapsuleGeometry(.018,.11,3,6),mat(color,.24,name==='Pearls'?.2:0));const a=i/count*Math.PI*2;b.position.set(Math.cos(a)*.09,.02,Math.sin(a)*.09);if(name==='Sprinkles')b.rotation.z=(i%2?.8:-.8);g.add(b)}return g}
if(name==='Candle'){const b=new THREE.Mesh(new THREE.CylinderGeometry(.045,.05,.38,12),mat('#fff5d5'));g.add(b);const stripe=new THREE.Mesh(new THREE.CylinderGeometry(.047,.052,.045,12),mat('#e98da7'));stripe.position.y=-.07;g.add(stripe);const flame=new THREE.Mesh(new THREE.SphereGeometry(.055,10,8),new THREE.MeshBasicMaterial({color:'#ffbd4a'}));flame.scale.set(.65,1.45,.65);flame.position.y=.24;g.add(flame);return g}
if(name==='Bow'||name==='Ribbon'){const color=name==='Bow'?'#e77d9a':'#d99caa';for(const sign of [-1,1]){const loop=new THREE.Mesh(new THREE.TorusGeometry(.105,.035,8,18,.95*Math.PI),mat(color,.32));loop.position.x=sign*.1;loop.rotation.z=sign>0?-.3:Math.PI+.3;g.add(loop)}const knot=new THREE.Mesh(new THREE.SphereGeometry(.055,10,8),mat('#f6c6d0'));g.add(knot);if(name==='Ribbon'){const tail=new THREE.Mesh(new THREE.BoxGeometry(.3,.045,.045),mat(color));tail.position.y=-.13;g.add(tail)}return g}
