if(name==='Rosette'){for(let i=0;i<8;i++){const a=i*Math.PI/4,b=new THREE.Mesh(new THREE.SphereGeometry(.075,12,10),mat(state.frost,.3));b.position.set(Math.cos(a)*.09,.02,Math.sin(a)*.09);g.add(b)}const c=new THREE.Mesh(new THREE.SphereGeometry(.075,12,10),mat(state.frost,.28));c.position.y=.05;g.add(c);return g}
if(name==='Frosting swoosh'||name==='Brush mark'||name==='Smooth finish'){const b=new THREE.Mesh(new THREE.SphereGeometry(name==='Frosting swoosh'?.19:.14,18,12),mat(state.frost,.3));b.scale.set(1,.3,1);g.add(b);return g}
if(name==='Chocolate drizzle'){const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(-.25,.04,0),new THREE.Vector3(-.12,.05,.09),new THREE.Vector3(0,.04,-.08),new THREE.Vector3(.13,.05,.08),new THREE.Vector3(.25,.04,0)]);const line=new THREE.Mesh(new THREE.TubeGeometry(curve,24,.027,7,false),mat('#604037',.22));g.add(line);return g}
return fruit('Blueberry')}
function addDecoration(name,position,normal=new THREE.Vector3(0,1,0),scale=1,rotation=0,record=true){const obj=decoModel(name);obj.position.copy(position);const n=normal.clone().normalize();obj.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),n);obj.rotateY(rotation||Math.random()*.5);obj.scale.multiplyScalar(scale||1);obj.traverse(c=>{if(c.isMesh){c.castShadow=true;c.receiveShadow=true;c.userData.decorationOwner=obj}});obj.userData.decoration=true;obj.userData.name=name;cakeRoot.add(obj);decorObjects.push(obj);if(record)state.placed.push({name,position:position.toArray(),normal:n.toArray(),scale:scale||1,rotation:rotation||0});$('#placedCount').textContent=String(state.placed.length);$('#selectionName').textContent=`${state.placed.length} sweet ${state.placed.length===1?'detail':'details'}`;$('#selectionSub').textContent='Looking lovely already';return obj}
function saveSnapshot(){state.undo.push(state.placed.map(x=>({...x,position:[...x.position],normal:[...x.normal]})));if(state.undo.length>25)state.undo.shift();state.redo=[]}
function selectDecoration(obj){selectedObject=obj;$('#selectedPop').classList.remove('hidden');$('#selectionName').textContent=obj.userData.name;$('#selectionSub').textContent='Selected · tap +/− to adjust';}

