function selectDecoration(obj){selectedObject=obj;$('#selectedPop').classList.remove('hidden');$('#selectionName').textContent=obj.userData.name;$('#selectionSub').textContent='Selected · tap +/− to adjust';}
function onResize(){const w=mount.clientWidth,h=mount.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}
new ResizeObserver(onResize).observe(mount);onResize();
function updateCamera(){const d=6.9/zoom,phi=Math.max(.35,Math.min(1.25,Math.PI/3+rotX));camera.position.set(target.x+d*Math.sin(phi)*Math.sin(rotY),target.y+d*Math.cos(phi),target.z+d*Math.sin(phi)*Math.cos(rotY));camera.lookAt(target)}updateCamera();
function pointerDown(e){dragging=true;lastX=e.clientX;lastY=e.clientY;dragMoved=false;renderer.domElement.setPointerCapture(e.pointerId)}let dragMoved=false;
function pointerMove(e){if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;if(Math.abs(dx)+Math.abs(dy)>2)dragMoved=true;rotY-=dx*.008;rotX=Math.max(-.35,Math.min(.5,rotX+dy*.004));lastX=e.clientX;lastY=e.clientY;updateCamera()}
function pointerUp(e){dragging=false;if(!dragMoved)handleCakeTap(e)}
renderer.domElement.addEventListener('pointerdown',pointerDown);renderer.domElement.addEventListener('pointermove',pointerMove);renderer.domElement.addEventListener('pointerup',pointerUp);renderer.domElement.addEventListener('pointercancel',()=>dragging=false);
function handleCakeTap(e){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(e.clientX-rect.left)/rect.width*2-1;pointer.y=-((e.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const all=[];cakeRoot.traverse(o=>{if(o.isMesh)all.push(o)});const hits=raycaster.intersectObjects(all,false);if(!hits.length)return;let hit=hits[0],owner=hit.object.userData.decorationOwner;if(hit.object.userData.decoration)owner=hit.object;if(owner){selectDecoration(owner);return}if(!hit.object.userData.cakeSurface)return;$('#selectedPop').classList.add('hidden');selectedObject=null;const point=hit.point.clone(),normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);if(state.decor){saveSnapshot();addDecoration(state.decor,point.addScaledVector(normal,.075),normal);toast(`${state.decor} placed with love ✨`);return}const op=state.tool;saveSnapshot();if(op==='piping'){addDecoration('Rosette',point.addScaledVector(normal,.055),normal);toast('A pretty frosting rosette!')}
else if(op==='spatula'){addDecoration('Frosting swoosh',point.addScaledVector(normal,.035),normal);toast('Silky frosting, coming right up!')}
else if(op==='brush'){addDecoration('Brush mark',point.addScaledVector(normal,.035),normal);toast('A soft brush of color!')}
else if(op==='scraper'){state.frostStyle='smooth';$('#cakeStage').classList.add('polished');rebuildCake();state.placed.push({name:'Smooth finish',position:point.toArray(),normal:normal.toArray(),scale:1,rotation:0});toast('Smoother than butter! ✨')}
else if(op==='shaker'){for(let i=0;i<9;i++){const a=i*2.399,r=.08+Math.random()*.22,p=point.clone().add(new THREE.Vector3(Math.cos(a)*r,.01,Math.sin(a)*r));addDecoration('Sprinkles',p,normal,.55,Math.random()*6.28)}toast('A sprinkle shower! 🌈')}
else if(op==='drizzle'){addDecoration('Chocolate drizzle',point.addScaledVector(normal,.04),normal);toast('Glossy chocolate drizzle!')}
$('#placedCount').textContent=String(state.placed.length);persist()}
function animate(){requestAnimationFrame(animate);renderer.render(scene,camera)}animate();
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1900)}
function changeSelectedSize(amount){if(!selectedObject)return;const idx=decorObjects.indexOf(selectedObject);if(idx<0)return;const rec=state.placed[idx];if(!rec)return;rec.scale=Math.max(.45,Math.min(2.4,rec.scale+amount));selectedObject.scale.setScalar(rec.scale);}
$('#rotateItem').onclick=()=>{if(!selectedObject)return;selectedObject.rotateY(.45);const i=decorObjects.indexOf(selectedObject);if(state.placed[i])state.placed[i].rotation+=.45};$('#smallerItem').onclick=()=>changeSelectedSize(-.15);$('#biggerItem').onclick=()=>changeSelectedSize(.15);
$('#deleteItem').onclick=()=>{if(!selectedObject)return;const idx=decorObjects.indexOf(selectedObject);saveSnapshot();selectedObject.parent.remove(selectedObject);decorObjects.splice(idx,1);state.placed.splice(idx,1);selectedObject=null;$('#selectedPop').classList.add('hidden');$('#placedCount').textContent=String(state.placed.length);$('#selectionName').textContent=state.placed.length?`${state.placed.length} sweet details`:'A blank canvas';$('#selectionSub').textContent=state.placed.length?'Looking lovely already':'Ready for your first touch';persist();toast('Decoration removed')};
function restorePlaced(records){state.placed=records.map(x=>({...x}));rebuildCake()}
$('#undoBtn').onclick=()=>{if(!state.undo.length){toast('Nothing to undo yet');return}state.redo.push(state.placed.map(x=>({...x})));restorePlaced(state.undo.pop());toast('One little step back')};$('#redoBtn').onclick=()=>{if(!state.redo.length){toast('Nothing to redo yet');return}state.undo.push(state.placed.map(x=>({...x})));restorePlaced(state.redo.pop());toast('Back to the good stuff')};
$('#viewBtn').onclick=()=>{rotY=0;rotX=0;zoom=1;updateCamera();toast('A fresh view of your cake')};$('#zoomIn').onclick=()=>{zoom=Math.min(1.55,zoom+.12);updateCamera()};$('#zoomOut').onclick=()=>{zoom=Math.max(.72,zoom-.12);updateCamera()};
$$('.shape-choice').forEach(b=>b.onclick=()=>{$$('.shape-choice').forEach(x=>x.classList.toggle('selected',x===b));state.shape=b.dataset.shape;rebuildCake()});$('#sizeSelect').onchange=e=>{state.size=e.target.value;rebuildCake()};$('#layerSelect').onchange=e=>{state.layers=+e.target.value;rebuildCake()};$('#flavorSelect').onchange=e=>{state.flavor=e.target.value;rebuildCake();toast(`${e.target.value} cake layers baked!`)};
$$('.frost-type').forEach(b=>b.onclick=()=>{$$('.frost-type').forEach(x=>x.classList.toggle('selected',x===b));state.frostStyle=b.dataset.frost;rebuildCake();toast(`${b.textContent.trim()} finish selected`)});
$('#mixBtn').onclick=()=>$('#customColor').classList.toggle('hidden');$('#applyColor').onclick=()=>{setFrost($('#colorPicker').value);$('#customColor').classList.add('hidden')};
$('#resetBtn').onclick=()=>{if(state.placed.length)saveSnapshot();state.placed=[];state.shape='round';state.size='medium';state.layers=2;state.flavor='vanilla';state.frost='#f5a9bd';state.frostStyle='smooth';state.decor=null;$('#sizeSelect').value='medium';$('#layerSelect').value='2';$('#flavorSelect').value='vanilla';$$('.shape-choice').forEach(x=>x.classList.toggle('selected',x.dataset.shape==='round'));$$('.frost-type').forEach(x=>x.classList.toggle('selected',x.dataset.frost==='smooth'));$$('.swatch').forEach(x=>x.classList.toggle('active',x.title==='Vanilla rose'));rebuildCake();toast('A fresh cake, just for you!')};

