node --input-type=module <<'JS'
import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser=await chromium.launch({headless:true,args:['--no-sandbox','--enable-webgl','--use-gl=angle','--use-angle=swiftshader']});
const page=await browser.newPage({viewport:{width:1440,height:960}});
page.on('console',m=>{if(m.type()==='error')console.log('console error',m.text())}); page.on('pageerror',e=>console.log('pageerror',e.message));
await page.goto('http://localhost:3002'); await page.waitForTimeout(3000);
console.log('mount',await page.locator('#threeMount').evaluate(e=>({rect:e.getBoundingClientRect().toJSON(),canvas:e.firstElementChild.getBoundingClientRect().toJSON(),buffer:[e.firstElementChild.width,e.firstElementChild.height]})));
console.log('cake at center',await page.evaluate(()=>document.elementFromPoint(730,400)?.tagName));
await page.locator('[data-item="Strawberry"]').click();
const box=await page.locator('#threeMount canvas').boundingBox();
for(const [x,y] of [[.5,.52],[.5,.45],[.42,.5],[.6,.5],[.5,.6]]){await page.mouse.click(box.x+box.width*x,box.y+box.height*y);await page.waitForTimeout(150);console.log('tap',x,y,'placed=',await page.locator('#placedCount').textContent(),'toast=',await page.locator('#toast').textContent())}
await page.screenshot({path:'/tmp/opencode/cake-fixed.jpg',type:'jpeg',quality:55});
await browser.close();
